-- Existing organizations keep their current access until an administrator explicitly
-- saves the expanded role matrix. This default only applies to new organizations.
alter table public.organizations alter column role_permissions set default '{"admin":["View dashboard","View tasks","View leads","View all leads","Edit leads","Delete leads","View pipeline","View proposals","Create proposals","Send proposals","View content","View activities","View reports","Export data","Edit CRM settings","Manage users"],"manager":["View dashboard","View tasks","View leads","View all leads","Edit leads","Delete leads","View pipeline","View content","View activities","View reports","Export data"],"sales":["View dashboard","View tasks","View leads","Edit leads","View pipeline","View content","View activities"],"viewer":["View dashboard","View tasks","View leads"]}'::jsonb;
